import json, glob, collections
from pathlib import Path

# Look for user message types in director sessions
files = sorted(set(glob.glob(str(Path.home())+'/.claude-account-*/projects/*schema-semantic*director*/*.jsonl')))
seen = set()
unique_files = []
for f in files:
    b = Path(f).name
    if b not in seen:
        seen.add(b)
        unique_files.append(f)

# Inspect first 2 files for structure
for f in unique_files[:1]:
    with open(f) as fh:
        for i, line in enumerate(fh):
            if i > 30: break
            try:
                o = json.loads(line)
            except: continue
            t = o.get('type', '?')
            role = o.get('message', {}).get('role', '?') if isinstance(o.get('message'), dict) else '?'
            ts = o.get('timestamp','')[:16]
            # First chars of content
            content = o.get('message', {}).get('content', '')
            if isinstance(content, list):
                preview = []
                for c in content[:3]:
                    if isinstance(c, dict):
                        if c.get('type') == 'text':
                            preview.append('TEXT:' + c.get('text','')[:150])
                        elif c.get('type') == 'tool_use':
                            preview.append('TOOL:' + c.get('name',''))
                        elif c.get('type') == 'tool_result':
                            preview.append('RES:')
                        else:
                            preview.append(c.get('type',''))
                content_str = ' | '.join(preview)
            else:
                content_str = str(content)[:200]
            print(f'[{i}] [{ts}] type={t} role={role} | {content_str[:300]}')
